insert into public.services (title, slug, excerpt, body, category, tags, status, data, published_at)
values
  ('Plan your application or improve your statement.', 'graduate-applications', 'From choosing a direction to revising your statement, get support for the decisions and documents that need attention.', 'Connect your preparation to the opportunity and develop an application that answers its actual questions.', 'Graduate admissions', array[]::text[], 'published', '{"page":{"slug":"graduate-applications","category":"Graduate admissions","title":"Plan your application or improve your statement.","excerpt":"From choosing a direction to revising your statement, get support for the decisions and documents that need attention.","overviewTitle":"Admissions, scholarships and fellowships","overviewText":"Connect your preparation to the opportunity and develop an application that answers its actual questions.","overviewBullets":["Career Audit and application planning","SOP, personal statement and motivation letter review","Programme fit, funding and deadline discussion"],"offers":[{"title":"AI Career Audit","audience":"For applicants who need to understand their starting point.","bullets":["Goals and experience review","Preparation gaps and unanswered questions","A prioritised action plan"],"callToAction":"Start an AI Career Audit","href":"/career-audit"},{"title":"Statement review","audience":"For applicants who already have a draft.","bullets":["Feedback on structure, evidence and programme fit","Editorial guidance that preserves your voice","Comments on the application prompt and claims in your draft"],"callToAction":"Discuss a review","href":"/consultation"},{"title":"Application strategy","audience":"For applicants needing support across the process.","bullets":["Programme and funding shortlist discussion","Document and deadline planning","Application support agreed around your needs"],"callToAction":"Discuss your application","href":"/consultation"}],"noteTitle":"A review starts with your draft and the official instructions.","note":"Share the application question, word limit and target opportunity so we can discuss the feedback you need. Programme selection and scholarship eligibility require a separate check against current official sources."},"display_order":0}'::jsonb, now() - interval '0 seconds'),
  ('CV, LinkedIn and interview support.', 'career-documents', 'Explain the work you have done, the evidence behind it and its relevance to the roles you want.', 'Make your contribution easier to understand and show how it relates to the roles you want.', 'Career documents', array[]::text[], 'published', '{"page":{"slug":"career-documents","category":"Career documents","title":"CV, LinkedIn and interview support.","excerpt":"Explain the work you have done, the evidence behind it and its relevance to the roles you want.","overviewTitle":"CVs, LinkedIn and interviews","overviewText":"Make your contribution easier to understand and show how it relates to the roles you want.","overviewBullets":["CV review and rewriting","LinkedIn headline, About and experience sections","Interview practice with feedback on your examples"],"offers":[{"title":"CV review & rewrite","audience":"For professionals whose CV does not reflect their experience.","bullets":["Target-role discussion","Achievement and evidence development","Editable document delivery"],"callToAction":"Discuss your CV","href":"/consultation"},{"title":"LinkedIn support","audience":"For professionals refining their public profile.","bullets":["Headline and About section review","Experience and relevant language","Guidance on profile consistency"],"callToAction":"Discuss your profile","href":"/consultation"},{"title":"Interview preparation","audience":"For candidates preparing for a particular role.","bullets":["Role and employer context","Mock interview and feedback","Specific feedback on your examples"],"callToAction":"Discuss interview support","href":"/consultation"}],"noteTitle":"Start with an AI job audit.","note":"Assess your target roles, experience evidence and job search approach. Human CV, LinkedIn and interview support can be arranged separately after a free 15-minute consultation."},"display_order":1}'::jsonb, now() - interval '1 seconds'),
  ('Connect your experience to your MBA goals.', 'mba-applications', 'Build a coherent case for your next career step, the programme you choose and what you bring to the classroom.', 'Explain your career direction, leadership experience and reasons for choosing an MBA.', 'MBA applications', array[]::text[], 'published', '{"page":{"slug":"mba-applications","category":"MBA applications","title":"Connect your experience to your MBA goals.","excerpt":"Build a coherent case for your next career step, the programme you choose and what you bring to the classroom.","overviewTitle":"A clear case for business school","overviewText":"Explain your career direction, leadership experience and reasons for choosing an MBA.","overviewBullets":["School fit and application strategy","Essay development and review","MBA interview preparation"],"offers":[{"title":"Application direction","audience":"For candidates deciding where and how to apply.","bullets":["Career goal discussion","School fit and application planning","Profile strengths and gaps"],"callToAction":"Discuss your strategy","href":"/consultation"},{"title":"Essay development & review","audience":"For applicants working on MBA essay questions.","bullets":["Leadership and impact examples","Essay structure and specific evidence","Feedback that protects your own voice"],"callToAction":"Discuss your essays","href":"/consultation"},{"title":"MBA interview preparation","audience":"For candidates invited to an admissions interview.","bullets":["School fit and application context","Mock interview and feedback","Clearer examples and answers"],"callToAction":"Discuss preparation","href":"/consultation"}],"noteTitle":"Start with an honest look at your profile.","note":"We consider your academic preparation, experience and career plans together. Support cannot promise admission or replace a programme’s tests and eligibility requirements."},"display_order":2}'::jsonb, now() - interval '2 seconds')
on conflict (slug) do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  body = excluded.body,
  category = excluded.category,
  data = excluded.data,
  status = 'published',
  published_at = excluded.published_at,
  deleted_at = null,
  updated_at = now();

insert into public.app_settings (key, value)
values ('site_public_content', '{"service_faqs":[{"question":"I’m not sure which service I need.","answer":"Start with the AI Career Audit for job search or study applications. If you want to talk through your options, book a free 15-minute consultation."},{"question":"Can you review a draft I have written?","answer":"Yes. Share your draft, the official application prompt, word limit, opportunity link and deadline. We can then discuss the feedback your draft needs and agree the scope."},{"question":"How much will the support cost?","answer":"The fee depends on the service and agreed scope. Confirm what is included, the number of review rounds, the fee and delivery date before committing."},{"question":"Does support guarantee a job, admission or funding?","answer":"No. Careergrill can help you assess your preparation and develop clearer applications. Employers, universities and scholarship providers make their own decisions."}],"consultation_services":{"help":{"name":"Help choosing support","dropdownLabel":"Help me choose the right support","goalLabel":"Your goal or next step","goalPlaceholder":"For example, choosing between a job search and postgraduate study","stages":["I’m exploring my options","I’m starting an application","I have a draft","I have an interview invitation"],"deadlineLabel":"Your deadline, if known","support":[],"checklist":["The goal you are working towards","What you have already tried or prepared","Any opportunity or deadline you have in mind","The part of the process you want help with"],"closing":"Could you suggest a suitable next step and let me know what information you need from me?"},"statement":{"name":"Statement review","dropdownLabel":"Statement review · Admissions","goalLabel":"Programme, scholarship or fellowship","goalPlaceholder":"For example, MSc Education at your chosen university","stages":["I’m starting from scratch","I have notes or an outline","I have a draft","I need a final check"],"deadlineLabel":"Application deadline, if known","support":["Feedback on structure, evidence and programme fit","Editorial guidance that preserves your voice","Comments on the application prompt and claims in your draft"],"checklist":["Your statement or notes, if available","The application question and word limit","The programme or scholarship page","Your deadline and the feedback you want"],"closing":"Could you let me know what the review includes, your turnaround time and the fee?"},"applicationStrategy":{"name":"Application strategy","dropdownLabel":"Application strategy · Admissions","goalLabel":"Study or scholarship goal","goalPlaceholder":"For example, a funded master’s in public policy","stages":["I’m exploring my options","I have a shortlist","I have chosen an opportunity"],"deadlineLabel":"Application deadline, if known","support":["Programme and funding shortlist discussion","Document and deadline planning","Application support agreed around your needs"],"checklist":["Your study goal and relevant background","Any programmes or funding routes you are considering","The requirements you have checked","The decisions you need help making"],"closing":"Could you let me know how you could help me plan the application, what I should share and the fee?"},"cv":{"name":"CV review & rewrite","dropdownLabel":"CV review & rewrite · Career documents","goalLabel":"Target role or type of work","goalPlaceholder":"For example, communications assistant roles in NGOs","stages":["I’m starting from scratch","I have notes or an outline","I have a draft","I need a final check"],"deadlineLabel":"When would you like this ready? (optional)","support":["Target-role discussion","Achievement and evidence development","Editable document delivery"],"checklist":["Your current CV or notes about your experience","A target role or job description","Examples of your work and contribution","The date you need the CV ready"],"closing":"Could you share what the CV service includes, how long it would take and the fee?"},"linkedin":{"name":"